ORDER = ["LY-426","LY-427","LY-428","LY-429","LY-430","LY-432","LY-433","LY-434",
         "LY-436","LY-437","LY-439","LY-440","LY-441","LY-442","LY-443","LY-445",
         "LY-446","LY-449","LY-451","LY-452"]

def main():
    os.makedirs(BASE, exist_ok=True)
    sizes = {}
    for cid in ORDER:
        d = P[cid]
        obj = {
            "case_id": cid,
            "prediction_text": d["prediction_text"],
            "basis": d["basis"],
            "confidence": d["confidence"],
            "trigger": d["trigger"],
        }
        assert obj["case_id"] == cid
        assert isinstance(obj["prediction_text"], str) and len(obj["prediction_text"]) > 30
        assert isinstance(obj["basis"], str) and "liuyao" in obj["basis"]
        assert "systems_used" in obj["basis"]
        assert 0.0 <= obj["confidence"] <= 1.0
        t = obj["trigger"]
        assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
        assert all(isinstance(t[k], bool) for k in ("changed_main", "reserve_used", "disputed"))
        assert isinstance(t["reason"], str) and t["reason"]
        path = os.path.join(BASE, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=1)
        # per-file re-read assertion
        with open(path, encoding="utf-8") as f:
            back = json.load(f)
        assert back["case_id"] == cid and back["trigger"] == t
        sizes[cid] = os.path.getsize(path)
        print(cid, sizes[cid])
    cm = sum(1 for c in ORDER if P[c]["trigger"]["changed_main"])
    ru = sum(1 for c in ORDER if P[c]["trigger"]["reserve_used"])
    di = sum(1 for c in ORDER if P[c]["trigger"]["disputed"])
    print("TOTAL", len(ORDER), "changed_main", cm, "reserve_used", ru, "disputed", di)

if __name__ == "__main__":
    main()
